 int CraftingPage(CraftingBuilding building)=>building.Definition.id=="blacksmith"?smithPage:clothierPage;
 void SetCraftingPage(CraftingBuilding building,int page){if(building.Definition.id=="blacksmith")SetSmithPage(page);else SetClothierPage(page);sharedProcessingCatalogScroll=sharedProcessingOrderScroll=Vector2.zero;ResetWorkshopCostInspection();}
 void CloseCraftingBuilding(CraftingBuilding building){ResetWorkshopCostInspection();if(building.Definition.id=="blacksmith")CloseSmith();else CloseClothier();}
 string CraftingFeedback(CraftingBuilding building)=>building.Definition.id=="blacksmith"?smithFeedback:materialProcessingFeedback;
 void SetCraftingFeedback(CraftingBuilding building,string value){if(building.Definition.id=="blacksmith")smithFeedback=value;else materialProcessingFeedback=value;}
 int ProcessingSelection(ProcessingLine line)=>line.IsBars?smithBarRecipe:materialProcessingIndex;
 void SetProcessingSelection(ProcessingLine line,int value){ResetWorkshopCostInspection();if(line.IsBars)smithBarRecipe=Mathf.Clamp(value,0,line.RecipeCount-1);else materialProcessingIndex=Mathf.Clamp(value,0,line.RecipeCount-1);}
 string ProcessingAmount(ProcessingLine line)=>line.IsBars?smithAmountText:materialProcessingAmount;
 void SetProcessingAmount(ProcessingLine line,string value){if(line.IsBars)smithAmountText=value;else materialProcessingAmount=value;}
 int ProcessingQuantity(ProcessingLine line)=>int.TryParse(ProcessingAmount(line),out int value)?value:0;
 bool ProcessingEditing(ProcessingLine line)=>line.IsBars?smithEditingQuantity:materialProcessingEditing;
 void SetProcessingEditing(ProcessingLine line,bool editing){if(line.IsBars)smithEditingQuantity=editing;else materialProcessingEditing=editing;}
 void QueueProcessing(ProcessingLine line){if(line.Queue(ProcessingSelection(line),ProcessingQuantity(line),out string message)){city.RefreshSettlementPlan();Save();}SetCraftingFeedback(line.Building,message);}
 void ResearchProcessing(ProcessingLine line){if(line.IsBars)OpenBarSlotResearch();else OpenMaterialSlotResearch(line.Source);}
 void EquipmentSelection(CraftingRecipeSet set,out int row,out int column){bool light=set.Kind==EquipmentRecipeKind.Cloth||set.Kind==EquipmentRecipeKind.Leather;row=Mathf.Clamp(light?lightGearTier-1:smithMetal,0,set.Rows-1);column=Mathf.Clamp(light?gearSlot:smithSlot,0,set.Columns-1);}
 void SetEquipmentSelection(CraftingRecipeSet set,int row,int column){ResetWorkshopCostInspection();bool light=set.Kind==EquipmentRecipeKind.Cloth||set.Kind==EquipmentRecipeKind.Leather;if(light){lightGearTier=Mathf.Clamp(row+1,1,set.Rows);gearSlot=Mathf.Clamp(column,0,set.Columns-1);}else{smithMetal=Mathf.Clamp(row,0,set.Rows-1);if(set.Kind!=EquipmentRecipeKind.Weapon)smithSlot=Mathf.Clamp(column,0,set.Columns-1);}}
 EquipmentRecipeEntry SelectedEquipment(CraftingRecipeSet set){EquipmentSelection(set,out int row,out int column);return set.Entry(row,column,smithHeavyVeil);}
 void CraftEquipment(CraftingBuilding building){var page=building.Settings.pages[CraftingPage(building)];if(page.kind!=WorkshopPageKind.Equipment)return;var set=building.Equipment(page);var entry=SelectedEquipment(set);if(set.Craft(entry,out string message)){gearSlot=entry.slot;if(entry.material==3)selectedMetal=entry.row;RefreshMetalGear();Save();}SetCraftingFeedback(building,message);}
 void QueueEquipment(CraftingBuilding building){var set=building.Equipment(building.Settings.pages[CraftingPage(building)]);if(set.Queue(SelectedEquipment(set),out string message)){city.RefreshSettlementPlan();Save();}SetCraftingFeedback(building,message);}
 bool ReadCraftingBuildingInput(CraftingBuilding building){
  if(resourceFocus||ActionPressed(ControlAction.Resources))return ReadResourceController();var key=Keyboard.current;var pad=PreferredPad;int index=CraftingPage(building);var page=building.Settings.pages[index];ProcessingLine line=page.kind==WorkshopPageKind.Equipment?null:building.Line(page.family);
  if(workshopCostInspect&&(key?.escapeKey.wasPressedThisFrame==true||pad?.buttonEast.wasPressedThisFrame==true)){ResetWorkshopCostInspection();return true;}
  if(key?.escapeKey.wasPressedThisFrame==true||pad?.buttonEast.wasPressedThisFrame==true){if(resourceCategory>=0)LeaveResourceBar();else if(line!=null&&ProcessingEditing(line))SetProcessingEditing(line,false);else CloseCraftingBuilding(building);return true;}
  if(resourceCategory>=0)return true;
  if(pad?.leftShoulder.wasPressedThisFrame==true){SetCraftingPage(building,(index+building.Settings.pages.Length-1)%building.Settings.pages.Length);return true;}if(pad?.rightShoulder.wasPressedThisFrame==true){SetCraftingPage(building,(index+1)%building.Settings.pages.Length);return true;}
  if(line!=null&&!ProcessingEditing(line)&&ReadWorkshopCostInspection(line.Recipe(ProcessingSelection(line)).Length))return true;
  if(line==null){var inspected=SelectedEquipment(building.Equipment(page));if(ReadWorkshopCostInspection(inspected.ingredients.Length+(inspected.essence>0?1:0)))return true;}
  if(line!=null){if(ProcessingEditing(line)){if(key?.enterKey.wasPressedThisFrame==true){SetProcessingEditing(line,false);QueueProcessing(line);}return true;}MenuInput();return true;}
  var set=building.Equipment(page);EquipmentSelection(set,out int row,out int column);int down=key?.downArrowKey.wasPressedThisFrame==true||pad?.dpad.down.wasPressedThisFrame==true?1:key?.upArrowKey.wasPressedThisFrame==true||pad?.dpad.up.wasPressedThisFrame==true?-1:0;int side=key?.rightArrowKey.wasPressedThisFrame==true||pad?.dpad.right.wasPressedThisFrame==true?1:key?.leftArrowKey.wasPressedThisFrame==true||pad?.dpad.left.wasPressedThisFrame==true?-1:0;
  row=Mathf.Clamp(row+down,0,set.Rows-1);if(set.Kind==EquipmentRecipeKind.Weapon&&row==9&&side!=0)smithHeavyVeil=!smithHeavyVeil;else column=Mathf.Clamp(column+side,0,set.Columns-1);SetEquipmentSelection(set,row,column);
  if(key?.enterKey.wasPressedThisFrame==true||pad?.buttonSouth.wasPressedThisFrame==true)CraftEquipment(building);return true;
 }
